mapper.select:
SELECT CASE directory.directory_type WHEN '0' THEN 'DEPARTMENT' WHEN '1' THEN 'DOCTOR' WHEN '2' THEN 'WARD' WHEN '3' THEN 'BED' END AS directory_type, COUNT(1) AS total FROM md_hospital_directory directory INNER JOIN org_organization organizations ON organizations.id = directory.organization_id WHERE 1 = 0
OR organizations.organization_code IN
#{code}
AND organizations.organization_code = #{organizationCode}
AND directory.is_valid = 1 GROUP BY directory.directory_type ORDER BY directory.directory_type
